<template><view class="academic-settings"><text class="heading">班主任</text><text v-if="loading" class="state">正在读取</text><template v-else-if="ready"><picker v-if="editable" :range="choices" range-key="displayName" :value="choiceIndex" :disabled="saving||uncertain" @change="choose"><view class="teacher-select">{{selectedName}}<text>⌄</text></view></picker><text v-else class="state">{{assignedName||'未设置'}}</text><button v-if="editable" class="save" :disabled="saving||uncertain" :loading="saving" @tap="save">保存班主任</button></template><text v-if="error" class="error">{{error}}</text><button v-if="error" class="reload" :disabled="saving" @tap="load">重新读取</button></view></template>
<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import {academicMetadataApi,type HeadTeacherOption} from '@/api/academic-metadata';
import {headTeacherDraft} from '@/models/academic-metadata-draft';
import {getOrganizationSession} from '@/session/organization-session';
const props=defineProps<{token:string;scope:string;classId:string;editable:boolean}>();
const emit=defineEmits<{(e:'saved',name:string|null):void}>();
const options=ref<HeadTeacherOption[]>([]),selected=ref<string|null>(null),assignedName=ref<string|null>(null),loading=ref(false),saving=ref(false),uncertain=ref(false),ready=ref(false),error=ref('');let revision=0,alive=true,version=0;
const choices=computed(()=>[{userId:'',displayName:'未设置',classOrganizationIds:[props.classId]},...options.value]);
const choiceIndex=computed(()=>Math.max(0,choices.value.findIndex(t=>t.userId===(selected.value||''))));
const selectedName=computed(()=>choices.value.find(t=>t.userId===(selected.value||''))?.displayName||assignedName.value||'请选择');
function valid(){const org=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string}|undefined;return alive&&!!props.token&&getOrganizationSession()?.accessToken===props.token&&org?.accessToken===props.token&&org?.organizationId===props.scope;}
function current(n:number){return revision===n&&valid();}
function choose(event:{detail:{value:string|number}}){if(!saving.value&&!uncertain.value)selected.value=choices.value[Number(event.detail.value)]?.userId||null;}
async function load(){if(saving.value)return;const n=++revision;loading.value=true;ready.value=false;error.value='';try{if(!valid())throw Error('组织或账号已变化，请重新进入');const [metadata,candidates]=await Promise.all([academicMetadataApi.readClass(props.token,props.scope,props.classId),props.editable?academicMetadataApi.headTeacherOptions(props.token,props.scope,props.classId):Promise.resolve([])]);if(!current(n))return;if(metadata.classId!==props.classId||!Number.isInteger(metadata.versionNo)||metadata.versionNo<0)throw Error('班级响应范围或版本不一致');options.value=candidates.filter(t=>t.classOrganizationIds.includes(props.classId));selected.value=metadata.headTeacherUserId;assignedName.value=metadata.headTeacherName||null;version=metadata.versionNo;uncertain.value=false;ready.value=true;}catch(e){if(current(n))error.value=e instanceof Error?e.message:'班主任读取失败';}finally{if(n===revision)loading.value=false;}}
async function save(){if(!ready.value||!props.editable||saving.value||loading.value||uncertain.value||!valid())return;const n=revision;let attempted=false;error.value='';try{const draft=headTeacherDraft(props.classId,selected.value,version,options.value);saving.value=true;attempted=true;const result=await academicMetadataApi.updateClass(props.token,props.scope,props.classId,draft.headTeacherUserId,draft.versionNo);if(!current(n))return;if(result.classId!==props.classId||result.versionNo!==version+1||result.headTeacherUserId!==draft.headTeacherUserId)throw Error('保存结果待核对，请重新读取');version=result.versionNo;assignedName.value=options.value.find(t=>t.userId===result.headTeacherUserId)?.displayName||null;emit('saved',assignedName.value);}catch(e){if(current(n)){uncertain.value=attempted;error.value=e instanceof Error?e.message:'保存结果待确认，请重新读取';}}finally{if(n===revision)saving.value=false;}}
watch(()=>[props.token,props.scope,props.classId,props.editable],()=>{++revision;options.value=[];selected.value=null;assignedName.value=null;ready.value=false;saving.value=false;uncertain.value=false;void load();},{immediate:true});onBeforeUnmount(()=>{alive=false;++revision;options.value=[];});
</script>
<style scoped>.academic-settings{padding:28rpx;background:#fff;border-radius:24rpx;margin-bottom:24rpx}.heading{display:block;font-size:30rpx;font-weight:600;color:#193d30;margin-bottom:22rpx}.teacher-select{display:flex;justify-content:space-between;padding:22rpx;background:#f3f7f4;border:1rpx solid #d9e5dc;border-radius:16rpx;font-size:28rpx;color:#284b3b}.save,.reload{margin:22rpx 0 0;line-height:76rpx;background:#155e45;border-radius:18rpx;color:white;font-size:28rpx}.reload{background:#eef5ef;color:#315f48}.state{font-size:27rpx;color:#708577}.error{display:block;color:#b35145;font-size:25rpx;margin-top:16rpx}button::after{border:0}</style>
